'use strict'

const kUrl = Symbol('url')

class Client {
  constructor () {
    this.calls = 0
    this[kUrl] = new URL('http://localhost:1234')
  }

  /**
   * @param {number} value
   * @returns {number}
   */
  dispatch (value) {
    value++
    this.calls++
    return value
  }
}

module.exports = { Client }
